{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.weekly_channel_performance as with params as ( select dateadd(day, -1, current_date()) as as_of_date, date_trunc(\'month\', dateadd(day, -1, current_date())) as as_of_month, day(dateadd(day, -1, current_date())) as cutoff_day ), cost_price_map as ( select sku_group, cost_price, category from SNITCH_DB.MAPLEMONK.base_product qualify row_number() over (partition by sku_group order by cost_price desc) = 1 ), cat_mp as ( select case when left(UPPER(TRIM(SKUGROUP)),2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)),\'-\',0) else UPPER(TRIM(SKUGROUP)) end as sku_group, case when category = \'Jacket\' then \'Jackets\' when category = \'Jacket\' then \'Jackets\' when category in (\'PYJAMAS\',\'Night Suit & Pyjamas\',\'Joggers & Trackpants\',\'Trackpants\',\'JOGGERS\') then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\',\'Chinos\') then \'Trousers\' else category end as category from snitch_db.maplemonk.uc_final_item_master qualify row_number() over (partition by case when left(UPPER(TRIM(SKUGROUP)),2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)),\'-\',0) else UPPER(TRIM(SKUGROUP)) end order by case when category = \'Jacket\' then \'Jackets\' when category = \'Jacket\' then \'Jackets\' when category in (\'PYJAMAS\',\'Night Suit & Pyjamas\',\'Joggers & Trackpants\',\'Trackpants\',\'JOGGERS\') then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\',\'Chinos\') then \'Trousers\' else category end asc) = 1 ), shopify as ( select to_date(\"Original Invoice Date \", \'DD-MM-YYYY\') as date, trim(upper(REVERSE(SUBSTRING(REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\',REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\"))))) AS sku_group, \'Shopify\' as Channel, sum(qty)::int as quantity, sum(sales)::int as sales, sum((mrp*qty))::int as mrp, sum(total)::int as total, sum(coalesce(try_to_number(nullif(regexp_replace(\"GRN Price Without Tax\", \'[^0-9.-]\', \'\'), \'\')), 0)*coalesce(try_to_number(nullif(regexp_replace(qty, \'[^0-9.-]\', \'\'), \'\')), 0))::int as cost_price from snitch_db.maplemonk.uc_get_tally_gst_report where \"Channel Ledger\" = \'Snitch\' and entity = \'NEW_INVOICE\' group by 1,2,3 ), shopify_main as ( select a.date, b.category, a.Channel, sum(quantity) as quantity, sum(total) as sales, sum(mrp-total) as discount, sum(a.cost_price) as cost_price from shopify a left join cost_price_map b on a.sku_group = b.sku_group group by 1,2,3 ), mp_main_pre as ( select to_date(\"Original Invoice Date \", \'DD-MM-YYYY\') as date, trim(upper(REVERSE(SUBSTRING(REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\"))))) AS sku_group, case when \"Channel Ledger\" in (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\') then \'MP_Ajio\' when \"Channel Ledger\" in (\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\') then \'MP_Amazon\' when \"Channel Ledger\" in (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') then \'MP_Myntra_PPMP\' when \"Channel Ledger\" in (\'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\') then \'MP_Nykaa\' else \'others\' end as Channel, sum(qty) as quantity, sum(case when \"Channel Ledger\" in (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\',\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\',\'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\') then total when \"Channel Ledger\" in (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\') then (total/0.68)::INT ELSE SALES END)::int AS SALES, sum(coalesce(try_to_number(nullif(regexp_replace(MRP, \'[^0-9.-]\', \'\'), \'\')), 0)*coalesce(try_to_number(nullif(regexp_replace(qty, \'[^0-9.-]\', \'\'), \'\')), 0)) as MRP, sum(coalesce(try_to_number(nullif(regexp_replace(\"GRN Price Without Tax\", \'[^0-9.-]\', \'\'), \'\')), 0)*coalesce(try_to_number(nullif(regexp_replace(qty, \'[^0-9.-]\', \'\'), \'\')), 0) ) as cp from snitch_db.maplemonk.uc_get_tally_gst_report where \"Channel Ledger\" in (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\',\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\',\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\',\'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\') group by 1,2,3 ), mp_main as ( select a.date, b.category, a.Channel, sum(quantity) as quantity, sum(sales) as sales, sum(mrp-sales) as discount, sum(cp) as cost_price from mp_main_pre a left join cost_price_map b on a.sku_group = b.sku_group group by 1,2,3 ), offline_main as ( select b.order_date::date as date, coalesce(cp.category, \'others\') as category, \'Store\' as channel, sum(b.shipping_quantity)::int as quantity, sum(b.selling_price)::int as sales, sum(discount)::int as discount, (sum(cp.cost_price * b.shipping_quantity))::int as cost_price from snitch_db.maplemonk.store_fact_items_offline b left join cost_price_map cp on b.sku_group = cp.sku_group where coalesce(cp.category,\'others\') <> \'others\' and lower(b.sku_group) not like \'cb%\' AND b.marketplace_mapped not in (\'SNITCH - WH - B2B\',\'SNITCH - SNITCH X\',\'SNITCH - WH - M P\',\'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\',\'SNITCH - WH - U.P\',\'SNITCH - WH - NORTH\',\'SNITCH - WH - YELHANKA\',\'SNITCH - WH - YELHANKA\' , \'SNITCH - WH - EMIZA\',\'SNITCH - WH - YELHANKA 2\') and lower(b.sku_group) not like \'cb%\' and b.doc_prefix not in (\'OMS\',\'QCOM\') group by 1,2,3 ), myntra_sor as ( select TO_DATE(order_created_date, \'YYYYMMDD\') AS date, b.category, \'MP_myntra_SOR\' as channel, sum(sales) as quantity, sum(replace(revenue,\',\',\'\')) as sales, sum(replace(\"MRP_Sales \",\',\',\'\')-replace(revenue,\',\',\'\')) as discount, sum(replace(cogsxqty,\',\',\'\')) as cost_price from snitch_db.maplemonk.google_sheets_myntra_sor a left join cat_mp b on upper(trim(a.\"Style \")) = b.sku_group group by 1,2,3 ), flipkart_sor as ( select TO_DATE(order_date_key, \'YYYYMMDD\') AS date, category, \'MP_flipkart_SOR\' as channel, sum(replace(units,\',\',\'\')) as quantity, sum(replace(\"SPXQty \",\',\',\'\')) as sales, sum(replace(\"MRP Rev\",\',\',\'\')-replace(SPXQty_excl_GST,\',\',\'\')) as discount, sum(replace(\"Cogsxunits \",\',\',\'\')) as cost_price from snitch_db.maplemonk.google_sheets_flipkart_sor a left join cat_mp b on upper(trim(a.\"Style \")) = b.sku_group group by 1,2,3 ), slikk as ( select TO_DATE(order_date, \'DD-MM-YYYY\') AS date, category, \'MP_slikk\' as channel, sum(total_quantity) as quantity, sum(total_amount) as sales, sum((mrp*total_quantity)-total_amount) as discount, sum(\"COGSxQty \") as cost_price from snitch_db.maplemonk.google_sheets_slikk a left join cat_mp b on upper(trim(a.\"Style \")) = b.sku_group group by 1,2,3 ), base as ( select * from shopify_main union all select * from offline_main union all select * from mp_main union all select * from myntra_sor union all select * from flipkart_sor union all select * from slikk ), base_filtered as ( select b.* from base b join params p on 1=1 where b.date <= p.as_of_date ), daily as ( select date, category, channel, sum(quantity)::number as quantity, sum(sales)::number as sales, sum(discount)::number as discount, sum(cost_price)::number as cost_price from base_filtered group by 1,2,3 ), daily_final as ( select d.date, d.category, d.channel, d.sales, d.quantity, d.discount, d.cost_price, lag(d.sales) over (partition by d.category, d.channel order by d.date) as prev_day_sales, case when lag(d.sales) over (partition by d.category, d.channel order by d.date) = 0 then null else (d.sales - lag(d.sales) over (partition by d.category, d.channel order by d.date)) / lag(d.sales) over (partition by d.category, d.channel order by d.date) end as dod_growth from daily d ), monthly_full as ( select date_trunc(\'month\', date) as month_start, category, channel, sum(sales)::number as sales_full from daily group by 1,2,3 ), monthly_mtd_limited as ( select date_trunc(\'month\', d.date) as month_start, d.category, d.channel, sum(d.sales)::number as sales_mtd from daily d join params p on 1=1 where day(d.date) <= p.cutoff_day and date_trunc(\'month\', d.date) in ( p.as_of_month, dateadd(month, -1, p.as_of_month), dateadd(year, -1, p.as_of_month) ) group by 1,2,3 ), month_cat_channel as ( select month_start, category, channel from monthly_full union select month_start, category, channel from monthly_mtd_limited ), cur_monthly as ( select u.month_start, u.category, u.channel, coalesce(f.sales_full, 0) as sales_full, coalesce(m.sales_mtd, 0) as sales_mtd from month_cat_channel u left join monthly_full f on u.month_start = f.month_start and u.category = f.category and u.channel = f.channel left join monthly_mtd_limited m on u.month_start = m.month_start and u.category = m.category and u.channel = m.channel ), monthly_growth as ( select c.month_start, c.category, c.channel, case when c.month_start = p.as_of_month then c.sales_mtd else c.sales_full end as month_sales, case when c.month_start = p.as_of_month then coalesce(pm.sales_mtd, 0) else coalesce(pm.sales_full, 0) end as prev_month_sales, case when c.month_start = p.as_of_month then coalesce(py.sales_mtd, 0) else coalesce(py.sales_full, 0) end as prev_year_sales, case when ( case when c.month_start = p.as_of_month then coalesce(pm.sales_mtd, 0) else coalesce(pm.sales_full, 0) end ) = 0 then null else ( (case when c.month_start = p.as_of_month then c.sales_mtd else c.sales_full end) - (case when c.month_start = p.as_of_month then coalesce(pm.sales_mtd, 0) else coalesce(pm.sales_full, 0) end) ) / (case when c.month_start = p.as_of_month then coalesce(pm.sales_mtd, 0) else coalesce(pm.sales_full, 0) end) end as mom_growth, case when ( case when c.month_start = p.as_of_month then coalesce(py.sales_mtd, 0) else coalesce(py.sales_full, 0) end ) = 0 then null else ( (case when c.month_start = p.as_of_month then c.sales_mtd else c.sales_full end) - (case when c.month_start = p.as_of_month then coalesce(py.sales_mtd, 0) else coalesce(py.sales_full, 0) end) ) / (case when c.month_start = p.as_of_month then coalesce(py.sales_mtd, 0) else coalesce(py.sales_full, 0) end) end as yoy_growth from cur_monthly c join params p on 1=1 left join cur_monthly pm on pm.month_start = dateadd(month, -1, c.month_start) and pm.category = c.category and pm.channel = c.channel left join cur_monthly py on py.month_start = dateadd(year, -1, c.month_start) and py.category = c.category and py.channel = c.channel ) select d.date, date_trunc(\'month\', d.date) as month_start, d.category, d.channel, d.sales, d.quantity, d.discount, d.cost_price, d.prev_day_sales, d.dod_growth, mg.month_sales, mg.prev_month_sales, mg.prev_year_sales, mg.mom_growth, mg.yoy_growth from daily_final d left join monthly_growth mg on mg.month_start = date_trunc(\'month\', d.date) and mg.category = d.category and mg.channel = d.channel order by d.date, d.category, d.channel ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

